contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Fund the test contract with enough ether to make the deposit.
        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        if (!reverted) {
            // Successful CashOut: balance decreases exactly by the amount, and the contract sends out exactly that amount.
            assert(balBefore >= cashOutAmount && balAfter == balBefore - cashOutAmount);
            assert(contractBalBefore >= cashOutAmount && contractBalAfter == contractBalBefore - cashOutAmount);
        } else {
            // Reverted CashOut: balance and contract balance must not change.
            assert(balAfter == balBefore);
            assert(contractBalAfter == contractBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(depositAmount >= c.MinDeposit());

        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        bool reverted;
        try c.CashOut(balBefore) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        assert(!reverted && balBefore == depositAmount && balAfter == 0 && contractBalBefore >= balBefore && contractBalAfter == contractBalBefore - balBefore);
    }

    receive() external payable {}
}

