contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint min = c.MinDeposit();
        uint beforeSelf = c.balances(address(this));
        uint beforeC = address(c).balance;

        // The deposit is permitted only if amount >= MinDeposit; below that, Deposit() is a no-op.
        bool depositAccepted;
        try c.Deposit{value: amount}() { depositAccepted = true; } catch { depositAccepted = false; }

        uint afterSelf = c.balances(address(this));
        uint afterC = address(c).balance;

        assert(
            (amount < min && depositAccepted && afterSelf == beforeSelf && afterC == beforeC) ||
            (amount >= min && depositAccepted && afterSelf == beforeSelf + amount && afterC == beforeC + amount)
        );
    }

    receive() external payable {}
}

