pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 depositAmount, uint256 cashOutAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount >= c.MinDeposit());
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(cashOutAmount <= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeContrBal = address(c).balance;
        try c.CashOut(cashOutAmount) {} catch { return; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterContrBal = address(c).balance;
        assertTrue(afterBal == beforeBal - cashOutAmount && afterContrBal == beforeContrBal - cashOutAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 cashOutAmount) public {
        _run(depositAmount, cashOutAmount);
    }

    receive() external payable {}
}

