        } catch {
            reverted = true;
        }
        uint256 balAfterCashOut;
        try c.balances(address(this)) returns (uint256 __r) { balAfterCashOut = __r; } catch { return; }
        assertTrue(depositOk && !reverted && balAfterCashOut == 0 && address(this).balance == ethBefore + cashOutToUse);
    }

    function testFuzz_run(uint256 depositAmount, uint256 cashOutAmount) public {
        _run(depositAmount, cashOutAmount);
    }

    receive() external payable {}
}
